document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector("script[data-blur-id]");if(!e)return;const s=e.getAttribute("data-blur-id"),o=Number(e.getAttribute("data-scroll-divisor")||300),t=document.getElementById(s);if(!t)return;const n=()=>{const e=window.pageYOffset||document.documentElement.scrollTop||0,i=600,n=Math.max(0,e-i),s=n/o;console.log(`Scroll: ${e}, Effective: ${n}, Opacity: ${s}`),t.style.opacity=s};window.addEventListener("scroll",n),n()})